INSERT INTO master_catalog (item_id, generic_name, brand_name, category, dosage_form, requires_prescription, indications, dosage_instructions, packaging, side_effects, image_url) VALUES
  (1, 'Paracetamol', 'Biogesic', 'Pain Relief', '500mg Tablet', false, 'For the relief of minor aches and pains such as headache, toothache, muscle ache, backache, arthritis, and reduction of fever.', 'Adults and children 12 years and older: 1 to 2 tablets every 4 to 6 hours as needed. Maximum 8 tablets (4,000mg) in 24 hours.', 'Blister pack of 10 tablets (Box of 100)', 'Rare when used as directed. Overdose may cause severe liver damage.', '/medicines/biogesic.svg'),
  (2, 'Ibuprofen + Paracetamol', 'Alaxan FR', 'Pain Relief', '200mg / 325mg Capsule', false, 'Fast relief of moderate to severe body aches, muscle pain, stiff neck, joint pain, arthritis, and sports injuries.', 'Adults and children 12 years and older: 1 capsule every 6 hours after meals as needed. Do not take on an empty stomach.', 'Blister pack of 10 red & orange capsules', 'May cause stomach discomfort, nausea, or heartburn. Avoid if having active peptic ulcers.', '/medicines/alaxan-fr.svg'),
  (3, 'Ibuprofen', 'Medicol Advance', 'Pain Relief', '400mg Liquid Gel Softgel', false, 'Fast-absorbing relief of severe headache, migraine, toothache, dysmenorrhea (menstrual cramps), and muscular pain.', 'Adults: 1 softgel every 6 to 8 hours with food or milk. Do not exceed 3 softgels (1,200mg) in 24 hours.', 'Blister pack of 10 orange clear liquid softgels', 'Stomach irritation, dizziness. Take with food or a full glass of water.', '/medicines/medicol-advance.svg'),
  (4, 'Ibuprofen', 'Advil Liqui-Gels', 'Pain Relief', '200mg Softgel Capsule', false, 'Rapid relief of tough headaches, backaches, toothaches, menstrual pain, and minor arthritis aches.', 'Adults: 1 to 2 softgels every 4 to 6 hours while symptoms persist. Maximum 6 softgels in 24 hours.', 'Bottle of 30 liquid softgels', 'Mild stomach upset, nausea, dizziness. Take after meals.', '/medicines/advil-liqui-gels.svg'),
  (5, 'Paracetamol', 'Tempra Syrup', 'Pain Relief', '120mg / 5mL Syrup 60mL', false, 'Effective relief of fever and pain in children due to colds, flu, immunization reactions, and teething.', 'Children 1-5 years: 5mL to 10mL every 4-6 hours. Follow pediatric dosage chart.', 'Amber glass bottle 60mL with measuring cup (Strawberry flavor)', 'Extremely well-tolerated in pediatric patients when given at correct dose.', '/medicines/tempra-syrup.svg'),
  (6, 'Paracetamol', 'Calpol Infant Drops', 'Pain Relief', '100mg / mL Infant Drops 15mL', false, 'Fast, gentle fever and pain relief for babies and infants aged 0 to 24 months. Orange flavored.', 'Infants 3-12 months: 0.6mL to 1.2mL using calibrated oral dropper every 4-6 hours.', '15mL bottle with graduated safety dropper', 'Safe for infants at calibrated dose. Consult pediatrician if fever exceeds 3 days.', '/medicines/calpol-drops.svg'),
  (7, 'Paracetamol + Caffeine', 'Panadol Extra', 'Pain Relief', '500mg / 65mg Caplet', false, 'Formulated with caffeine for stronger, enhanced relief of stubborn migraine, headache, back pain, and sore muscles.', 'Adults: 1 to 2 caplets every 4 to 6 hours as needed. Maximum 8 caplets in 24 hours.', 'Blister strip of 10 red caplets', 'May cause restlessness or difficulty sleeping if taken near bedtime due to caffeine.', '/medicines/panadol-extra.svg'),
  (8, 'Phenylephrine + Chlorphenamine + Paracetamol', 'Neozep Forte', 'Cold & Flu', '10mg / 2mg / 500mg Tablet', false, 'Complete relief of clogged nose, runny nose, postnasal drip, itchy/watery eyes, sneezing, body ache, and fever.', 'Adults and children 12 years and older: 1 tablet every 6 hours, or as directed by a doctor.', 'Blister foil pack of 10 green & yellow tablets', 'Drowsiness, dry mouth, mild dizziness. Avoid driving or operating machinery.', '/medicines/neozep-forte.svg'),
  (9, 'Phenylephrine + Chlorphenamine + Paracetamol', 'Bioflu', 'Cold & Flu', 'Tablet', false, 'Multi-symptom relief for the flu, cough from postnasal drip, headache, fever, sore throat, and nasal congestion.', 'Adults and children 12 years and over: 1 tablet orally every 6 hours.', 'Blister foil pack of 10 tri-colored tablets', 'May cause drowsiness and sedation. Take with a glass of water.', '/medicines/bioflu.svg'),
  (10, 'Phenylpropanolamine + Chlorphenamine + Paracetamol', 'Decolgen Forte', 'Cold & Flu', '25mg / 2mg / 500mg Tablet', false, 'Decongests nasal sinuses and relieves fever, headache, and allergic nasal secretions associated with common cold.', 'Adults: 1 tablet every 6 hours, or as prescribed by a physician.', 'Blister pack of 10 tablets', 'Mild drowsiness, dry mouth, elevated blood pressure in hypertensive individuals.', '/medicines/decolgen-forte.svg'),
  (11, 'Carbocisteine', 'Solmux', 'Cold & Flu', '500mg Capsule', false, 'Mucolytic agent that melts and liquefies thick phlegm and mucus in productive cough, bronchitis, and asthma.', 'Adults and children 12 years and over: 1 capsule every 8 hours (3 times daily) after meals.', 'Blister strip of 10 red & green capsules', 'Generally safe; mild nausea or gastric discomfort may rarely occur.', '/medicines/solmux-capsule.svg'),
  (12, 'Carbocisteine', 'Solmux Pediatric Syrup', 'Cold & Flu', '100mg / 5mL Syrup 60mL', false, 'Pediatric mucolytic for children with cough with phlegm. Clears airways and facilitates easy breathing.', 'Children 2-4 years: 5mL (1 teaspoonful) every 8 hours. 4-7 years: 10mL every 8 hours.', '60mL bottle with pediatric dosing cup', 'Mild stomach upset or loose stools in rare instances.', '/medicines/solmux-syrup.svg'),
  (13, 'Dextromethorphan + Guaifenesin', 'Robitussin DM', 'Cold & Flu', 'Syrup 60mL', false, 'Controls dry, hacking cough and loosens stubborn chest congestion. Mentholated cherry formula.', 'Adults: 10mL every 4 hours as needed. Do not exceed 6 doses in 24 hours.', '60mL bottle with measuring cup', 'Dizziness, drowsiness, nausea. Drink plenty of water during use.', '/medicines/robitussin-dm.svg'),
  (14, 'Dextromethorphan + Phenylpropanolamine + Paracetamol', 'Tuseran Forte', 'Cold & Flu', '15mg / 25mg / 325mg Capsule', false, 'Relief of dry, nagging cough, nasal congestion, postnasal drip, headache, and fever from the flu.', 'Adults: 1 capsule every 6 hours, or as directed by a doctor.', 'Blister strip of 10 orange/yellow capsules', 'Drowsiness, mild dry mouth, restlessness.', '/medicines/tuseran-forte.svg'),
  (15, 'Camphor + Menthol + Eucalyptus Oil', 'Vicks VapoRub', 'Cold & Flu', 'Topical Ointment 25g', false, 'Topical soothing ointment for relief of nasal congestion, chest heaviness, and cough due to colds.', 'Rub gently on chest, throat, and back. May add 2 teaspoonfuls to hot water for steam inhalation.', '25g cobalt blue jar with green cap', 'For external use only. Avoid contact with eyes or open wounds.', '/medicines/vicks-vaporub.svg'),
  (16, 'Loperamide', 'Diatabs', 'Digestive', '2mg Capsule', false, 'Symptomatic control and rapid relief of acute non-specific diarrhea, food-borne diarrhea, and traveler’s diarrhea.', 'Adults: 2 capsules initially, then 1 capsule after each unformed watery stool. Maximum 8 capsules/day.', 'Foil blister pack of 4 capsules', 'Constipation if overused, dry mouth, mild abdominal cramps.', '/medicines/diatabs.svg'),
  (17, 'Aluminum Hydroxide + Magnesium Hydroxide + Simethicone', 'Kremil-S', 'Digestive', 'Chewable Tablet', false, 'Relief of hyperacidity, acid reflux, heartburn (hapdi), stomach ulcer pain, and gassy bloated stomach.', 'Chew 1 to 2 tablets 1 hour after meals and at bedtime, or when feeling acid pain.', 'Blister strip of 8 chewable tablets', 'Chalky taste. Aluminum may cause constipation, magnesium may cause laxative effect.', '/medicines/kremil-s.svg'),
  (18, 'Sodium Alginate + Sodium Bicarbonate', 'Gaviscon Double Action', 'Digestive', '10mL Liquid Sachet', false, 'Creates a protective physical barrier atop stomach contents to rapidly suppress GERD acid reflux and soothe heartburn.', 'Adults: Take 1 to 2 sachets (10-20mL) after meals and at bedtime.', 'Ready-to-drink 10mL tear-off foil sachet', 'Very safe; mild abdominal distension in rare cases.', '/medicines/gaviscon-double-action.svg'),
  (19, 'Hyoscine-N-butylbromide', 'Buscopan', 'Digestive', '10mg Sugar-Coated Tablet', false, 'Targeted antispasmodic relief for painful abdominal cramps, menstrual cramps (dysmenorrhea), and intestinal spasm.', 'Adults: 1 to 2 tablets 3 to 5 times daily with water as needed.', 'Blister strip of 10 round tablets', 'Dry mouth, mild tachycardia, temporary blurred vision.', '/medicines/buscopan.svg'),
  (20, 'Bisacodyl', 'Dulcolax', 'Digestive', '5mg Gastro-Resistant Tablet', false, 'Predictable overnight relief of constipation. Stimulates natural colon motility.', 'Adults and children over 10: 1 to 2 tablets at night. Acts within 6 to 12 hours.', 'Green box with blister of 10 enteric-coated tablets', 'Abdominal discomfort or cramping prior to bowel evacuation.', '/medicines/dulcolax.svg'),
  (21, 'Bacillus clausii Spores', 'Erceflora Gut Defense', 'Digestive', '2 Billion / 5mL Oral Suspension', false, 'Restores healthy intestinal bacterial flora altered by diarrhea, infections, or antibiotic therapy.', 'Adults: 2 to 3 mini-bottles per day. Shake and drink directly from vial.', '5mL tamper-evident plastic vial', 'Extremely safe; suitable for infants, children, and adults.', '/medicines/erceflora.svg'),
  (22, 'Loperamide', 'Imodium', 'Digestive', '2mg Capsule', false, 'Fast antidiarrheal action that calms intestinal hypermotility and firms up loose stool.', 'Take 2 capsules initially, then 1 capsule after each unformed stool. Maximum 8 capsules/day.', 'Blister strip of 6 green capsules', 'Dizziness, drowsiness, constipation if used excessively.', '/medicines/imodium.svg'),
  (23, 'Vitamin B-Complex + 500mg Vitamin C', 'Enervon-C', 'Vitamins', 'Tablet', false, 'Provides daily energy boost (B-Complex) and immune defense (500mg Vitamin C) against sickness and stress.', 'Adults: 1 tablet daily with food, preferably in the morning.', 'Blister pack of 10 bright orange tablets', 'Bright yellow urine (harmless due to riboflavin excretion).', '/medicines/enervon-c.svg'),
  (24, 'Ascorbic Acid', 'Poten-Cee Sugar-Free', 'Vitamins', '500mg Tablet', false, 'Enhances body resistance against colds, viral infections, and stress. Promotes healthy gums and skin collagen.', 'Adults: 1 to 2 tablets daily, or as directed by a healthcare professional.', 'Blister pack of 10 orange tablets', 'High doses may cause mild gastric acidity. Take after meals.', '/medicines/poten-cee.svg'),
  (25, 'Multivitamins + Minerals (Zinc + Vitamin A, C, E)', 'Conzace', 'Vitamins', 'Softgel Capsule', false, 'Potent immunity booster with Zinc and antioxidants A, C, and E for wound healing, skin health, and infection defense.', 'Adults: 1 softgel capsule once a day after a meal.', 'Blister strip of 10 brown liquid softgels', 'Take with food to prevent mild gastrointestinal sensation from zinc.', '/medicines/conzace.svg'),
  (26, 'B-Complex + Vitamin C + Calcium + Magnesium + Zinc', 'Berocca Performance', 'Vitamins', 'Effervescent Tablet', false, 'Fizzy energy & mental sharpness formula. Recharges physical stamina and sharpens cognitive alertness.', 'Drop 1 tablet into a glass of cold water (200mL). Drink once daily in the morning.', 'Metal tube of 10 effervescent tablets (Orange flavor)', 'Bright yellow urine due to Vitamin B2.', '/medicines/berocca.svg'),
  (27, 'Ascorbic Acid + Zinc', 'Ceelin Plus', 'Vitamins', 'Oral Drops 30mL', false, 'ZincPlus technology provides dual defense against sickness and fast recovery for infants and toddlers.', 'Infants 6-11 months: 0.5mL to 1mL daily using calibrated dropper.', '30mL glass dropper bottle (Apple flavor)', 'Well-tolerated pediatric formulation.', '/medicines/ceelin-plus.svg'),
  (28, 'Sodium Ascorbate', 'Fern-C', 'Vitamins', '500mg Capsule', false, 'Non-acidic Vitamin C. Gentle on stomach; safe for people with hyperacidity or GERD.', 'Adults: 1 to 2 capsules daily. Can be taken with or without meals.', 'Blister strip of 10 orange/clear capsules', 'Virtually non-irritating to stomach lining.', '/medicines/fern-c.svg'),
  (29, 'Multivitamins + Minerals + Amino Acids', 'Revicon Forte', 'Vitamins', 'Tablet', false, 'Helps fight physical exhaustion, boosts muscle stamina, and aids in rapid recovery from heavy physical labor.', 'Adults: 1 to 2 tablets daily after meals.', 'Blister pack of 10 red tablets', 'Very mild GI sensations in sensitive stomachs. Take after meals.', '/medicines/revicon-forte.svg'),
  (30, 'Cetirizine Dihydrochloride', 'Alnix', 'Allergy', '10mg Film-Coated Tablet', false, '24-hour non-drowsy relief from allergic rhinitis, hay fever, itchy nose, skin hives (urticaria), and watery eyes.', 'Adults and children over 12 years: 1 tablet (10mg) once daily with water.', 'Blister strip of 10 white film-coated tablets', 'Low incidence of drowsiness compared to first-generation antihistamines.', '/medicines/alnix.svg'),
  (31, 'Cetirizine', 'Allerkid', 'Allergy', '2.5mg / mL Oral Drops 10mL', false, 'Pediatric relief for allergic sneezing, chronic hives, and allergic cough in toddlers and children.', 'Children 2-5 years: 1mL (5mg) once daily or 0.5mL twice daily.', '10mL dropper bottle with safety cap', 'Very safe for kids at indicated weight-adjusted doses.', '/medicines/allerkid.svg'),
  (32, 'Loratadine', 'Claritin', 'Allergy', '10mg Tablet', false, 'True non-drowsy 24-hour relief of allergies, sinus itch, sneezing, and skin allergy rashes.', 'Adults and children 12 years and over: 1 tablet once daily on an empty stomach or with food.', 'Blister pack of 10 white oval tablets', 'Non-drowsy formula; dry mouth or headache in rare individuals.', '/medicines/claritin.svg'),
  (33, 'Cetirizine', 'Virlix', 'Allergy', '10mg Tablet', false, 'Rapid onset relief from allergic reactions, dust mite allergies, pet dander allergy, and eczema itch.', 'Adults: 1 tablet daily with water.', 'Blister foil strip of 10s', 'Mild dry mouth or slight fatigue in sensitive users.', '/medicines/virlix.svg'),
  (34, 'Povidone-Iodine 10%', 'Betadine Antiseptic Solution', 'First Aid', '10% Topical Solution 15mL', false, 'Golden standard antiseptic for disinfection of minor cuts, wounds, burns, and abrasions. Does not sting.', 'Apply full strength directly to clean wound area with sterile cotton or swab 2-3 times daily.', '15mL yellow bottle with dropper spout', 'For external use only. Discontinue if local skin irritation occurs.', '/medicines/betadine-antiseptic.svg'),
  (35, 'Hexetidine 0.1%', 'Bactidol Oral Antiseptic', 'First Aid', '0.1% Gargle Solution 60mL', false, 'Fast relief of sore throat, mouth ulcers (singaw), swollen gums, and bad breath caused by oral bacteria.', 'Swish and gargle 15mL (undiluted) for 30 seconds, then spit out. Do not swallow. Twice daily.', '60mL bottle with measuring cup', 'Mild transient alteration of taste sensation.', '/medicines/bactidol.svg'),
  (36, 'Methyl Salicylate + Menthol', 'Salonpas Medicated Patch', 'First Aid', 'Pain Relieving Patch (Pack of 10)', false, 'Direct transdermal relief for stiff neck, sore shoulders, backache, joint sprains, and muscle fatigue.', 'Clean and dry affected area. Apply 1 patch up to 8 hours. Maximum 3 to 4 times daily.', 'Resealable foil packet containing 10 adhesive patches', 'Mild skin redness or warming sensation at application site.', '/medicines/salonpas-patch.svg'),
  (37, 'Adhesive Bandages', 'Band-Aid Water Block', 'First Aid', 'Waterproof Strip (Pack of 10)', false, 'Protects everyday cuts, scrapes, and blisters from water, dirt, and bacteria with 100% waterproof seal.', 'Clean wound thoroughly, dry skin, and apply bandage over wound pad. Change daily or when wet.', 'Pack of 10 individually wrapped sterile strips', 'Hypoallergenic; suitable for sensitive skin.', '/medicines/band-aid-waterproof.svg'),
  (38, 'Hydrogen Peroxide 3%', 'Rhea Agua Oxigenada', 'First Aid', '3% 10 Vol Topical Liquid 60mL', false, 'Effervescent cleansing and decontamination of superficial dirty cuts, scratches, and minor sores.', 'Pour a small amount onto cotton and gently wipe over wound area. Effervesces on contact.', '60mL amber bottle with seal cap', 'Mild temporary bleaching of skin. Do not swallow.', '/medicines/agua-oxigenada.svg'),
  (39, 'Amoxicillin Trihydrate', 'Amoxil', 'Antibiotic', '500mg Capsule', true, 'Broad-spectrum penicillin antibiotic for bacterial respiratory, ENT, skin, and urinary tract infections.', 'Strictly as prescribed by a licensed physician. Complete the full course of treatment.', 'Foil blister of 10 capsules (Rx Required)', 'Diarrhea, nausea, allergic rash. NEVER dispense without valid physician prescription.', '/medicines/amoxil.svg'),
  (40, 'Losartan Potassium', 'Cozaar', 'Blood Pressure', '50mg Film-Coated Tablet', true, 'Maintenance treatment of essential hypertension (high blood pressure) and stroke prevention in hypertensive patients.', 'Take 1 tablet daily or as directed by cardiologist/physician. Do not abruptly stop taking.', 'Blister strip of 10 tablets (Rx Required)', 'Dizziness, low blood pressure, fatigue. Monitored strictly by physician.', '/medicines/cozaar.svg');
